#pragma once

#include <array>
#include <cstddef>

namespace mixxx {

// Autonomously generated by an AI agent.
// Reassembles a MIDI byte stream across arbitrary input chunks. SysEx views
// remain valid until the next byte is processed. Oversized messages are dropped
// in full so controller mappings never receive a truncated SysEx command.
// End of comment autonomously generated by an AI agent.
class MidiStreamParser {
  public:
    static constexpr std::size_t kMaxSysExSize = 1024;

    enum class MessageType { None,
        Short,
        SysEx };
    struct Message {
        MessageType type = MessageType::None;
        unsigned char status = 0;
        unsigned char data1 = 0;
        unsigned char data2 = 0;
        const unsigned char* sysexData = nullptr;
        std::size_t sysexSize = 0;
    };

    static int shortMessageDataLength(unsigned char status) {
        if (status < 0x80 || status == 0xF0 || status == 0xF4 ||
                status == 0xF5 || status == 0xF7) {
            return -1;
        }
        if (status >= 0xF8 || status == 0xF6) {
            return 0;
        }
        if (status == 0xF1 || status == 0xF3 ||
                (status & 0xF0) == 0xC0 || (status & 0xF0) == 0xD0) {
            return 1;
        }
        return 2;
    }

    void reset() {
        m_status = 0;
        m_dataIndex = 0;
        m_dataLength = 0;
        m_inSysEx = false;
        m_sysExOverflow = false;
        m_sysExSize = 0;
    }

    Message processByte(unsigned char byte) {
        if (byte >= 0xF8) {
            return {MessageType::Short, byte};
        }
        if (m_inSysEx) {
            if (byte == 0xF7) {
                appendSysEx(byte);
                m_inSysEx = false;
                if (!m_sysExOverflow) {
                    return {MessageType::SysEx, 0, 0, 0, m_sysEx.data(), m_sysExSize};
                }
                return {};
            }
            if (byte < 0x80) {
                appendSysEx(byte);
                return {};
            }
            reset();
        }
        if (byte >= 0x80) {
            m_status = 0;
            m_dataIndex = 0;
            m_dataLength = 0;
            if (byte == 0xF0) {
                m_inSysEx = true;
                m_sysExOverflow = false;
                m_sysExSize = 0;
                appendSysEx(byte);
                return {};
            }
            const int length = shortMessageDataLength(byte);
            if (length == 0) {
                return {MessageType::Short, byte};
            }
            if (length > 0) {
                m_status = byte;
                m_dataLength = length;
            }
            return {};
        }
        if (m_status == 0) {
            return {};
        }
        m_data[m_dataIndex++] = byte;
        if (m_dataIndex < m_dataLength) {
            return {};
        }
        const Message message{MessageType::Short,
                m_status,
                m_data[0],
                static_cast<unsigned char>(m_dataLength > 1 ? m_data[1] : 0)};
        m_dataIndex = 0;
        if (m_status >= 0xF0) {
            m_status = 0;
        }
        return message;
    }

  private:
    void appendSysEx(unsigned char byte) {
        if (m_sysExSize < m_sysEx.size()) {
            m_sysEx[m_sysExSize++] = byte;
        } else {
            m_sysExOverflow = true;
        }
    }

    unsigned char m_status = 0;
    std::array<unsigned char, 2> m_data{};
    int m_dataIndex = 0;
    int m_dataLength = 0;
    bool m_inSysEx = false;
    bool m_sysExOverflow = false;
    std::array<unsigned char, kMaxSysExSize> m_sysEx{};
    std::size_t m_sysExSize = 0;
};

} // namespace mixxx
